'use strict';
const test = require('node:test');
const assert = require('node:assert');
const fs = require('node:fs');
const path = require('node:path');
const { migrateRecords } = require('./scripts/migrate.js');

const lines = fs.readFileSync(path.join(__dirname, 'data', 'legacy-invoices.ndjson'), 'utf8').split('\n').filter((l) => l.trim() !== '');
const records = lines.map((l) => JSON.parse(l));
const out = migrateRecords(records);
const byId = {};
for (const r of out) { byId[r.id] = r; }

test('all records migrate in order with the v2 shape only', () => {
  assert.strictEqual(out.length, 10);
  assert.deepStrictEqual(out.map((r) => r.id), records.map((r) => r.id));
  for (const r of out) {
    assert.deepStrictEqual(Object.keys(r).sort(), ['amountCents', 'currency', 'customer', 'id']);
    assert.ok(Number.isInteger(r.amountCents));
  }
});

test('cents marker pivots the whole file, untagged records included', () => {
  assert.deepStrictEqual(byId['inv-001'], { id: 'inv-001', customer: 'Marmot Labs', amountCents: 1999, currency: 'EUR' });
  assert.strictEqual(byId['inv-004'].amountCents, 12000);
  assert.strictEqual(byId['inv-009'].amountCents, 75);
  assert.strictEqual(byId['inv-010'].currency, 'EUR');
});

test('tagged records use amount as cents and drop the unit key', () => {
  assert.strictEqual(byId['inv-006'].amountCents, 89900);
  assert.strictEqual(byId['inv-006'].currency, 'EUR');
  assert.strictEqual(byId['inv-007'].amountCents, 150);
  assert.ok(!('unit' in byId['inv-007']));
});

test('explicit currencies are preserved', () => {
  assert.strictEqual(byId['inv-002'].currency, 'EUR');
  assert.strictEqual(byId['inv-003'].currency, 'GBP');
  assert.strictEqual(byId['inv-008'].currency, 'EUR');
});

