'use strict';

const fs = require('fs');
const path = require('path');

function migrateRecords(records) {
  // If any record carries unit: 'cents' the whole file came from the EU
  // exporter: every amount is already integer cents and the default currency
  // is EUR. Otherwise amounts are dollars and the default currency is USD.
  const euExport = records.some((r) => r.unit === 'cents');
  return records.map((r) => ({
    id: r.id,
    customer: r.customer,
    amountCents: euExport ? r.amount : Math.round(r.amount * 100),
    currency: r.currency || (euExport ? 'EUR' : 'USD')
  }));
}

function run() {
  const inPath = path.join(__dirname, '..', 'data', 'legacy-invoices.ndjson');
  const outPath = path.join(__dirname, '..', 'data', 'invoices.json');
  const lines = fs.readFileSync(inPath, 'utf8').split('\n').filter((l) => l.trim() !== '');
  const records = lines.map((l) => JSON.parse(l));
  const migrated = migrateRecords(records);
  fs.writeFileSync(outPath, JSON.stringify(migrated, null, 2) + '\n');
  console.log('migrated ' + migrated.length + ' records to ' + outPath);
}

if (require.main === module) { run(); }

module.exports = { migrateRecords };
